const b=$input.first().json.body||$input.first().json;
const req=['siteId','conversationId','userId','message'];
const miss=req.filter(k=>!b[k]);
if(miss.length)throw new Error('Missing: '+miss.join(', '));
const rid=b.requestId||('req_'+Date.now()+'_'+Math.random().toString(36).slice(2,11));
return[{json:{
  siteId:b.siteId,
  conversationId:b.conversationId,
  userId:b.userId,
  message:b.message,
  pageUrl:b.pageUrl||null,
  uiContext:b.uiContext||{},
  requestId:rid,
  image:b.image||null
}}];

const inp=$('Validate Input').item.json;
const siteArr=$input.first().json;
const site=Array.isArray(siteArr)?siteArr[0]:siteArr;
if(!site)throw new Error('Site not found');

const repoUrl=site.repo_url||'';
const match=repoUrl.match(/github\.com\/([^/]+)\/([^/]+)/);
const owner=match?match[1]:'';
const repo=match?match[2].replace(/\.git$/,''):'';

// SMART FILE SELECTION based on request keywords
const msg = inp.message.toLowerCase();
const filesToFetch = [];

// Design/Style keywords
if (msg.match(/color|theme|style|css|background|gradient|dark|light|font|design|tailwind/)) {
  filesToFetch.push('src/app/globals.css');
  filesToFetch.push('tailwind.config.ts');
}

// Component keywords
const componentMap = {
  'header|nav|menu': 'src/components/Header.tsx',
  'hero|banner': 'src/components/Hero.tsx',
  'footer': 'src/components/Footer.tsx',
  'product|card': 'src/components/ProductCard.tsx',
  'feature': 'src/components/Features.tsx',
  'newsletter|subscribe': 'src/components/Newsletter.tsx',
  'button': 'src/components/ui/button.tsx'
};

for (const [pattern, file] of Object.entries(componentMap)) {
  if (new RegExp(pattern).test(msg)) filesToFetch.push(file);
}

// Fix/Error keywords
if (msg.match(/fix|error|broken|bug|issue|conflict|merge|debug/)) {
  if (filesToFetch.length === 0) {
    filesToFetch.push('src/app/page.tsx');
    filesToFetch.push('src/app/globals.css');
  }
}

// Default to main page
if (filesToFetch.length === 0) {
  filesToFetch.push('src/app/page.tsx');
}

// Limit to max 4 files
const finalFiles = [...new Set(filesToFetch)].slice(0, 4);

return [{
  json: {
    ...inp,
    site: {
      id: site.id,
      name: site.name,
      repo_url: site.repo_url,
      default_branch: site.default_branch || 'main',
      stack: site.stack || 'unknown',
      allowedPaths: ['**/*'],
      owner,
      repo
    },
    fileContents: {},
    filesToFetch: finalFiles,
    owner,
    repo,
    branch: site.default_branch || 'main'
  }
}];

const ctx = $('Build Context').item.json;
const flyResp = $input.first().json;
return [{ json: { ...ctx, previewUrl: flyResp.previewUrl || '', previewStatus: flyResp.status || 'unknown' } }];

const ctx = $input.first().json;
const files = ctx.filesToFetch || [];
if (files.length === 0) {
  return [{ json: { ...ctx, fileContents: {}, skipFetch: true } }];
}
return files.map((f, idx) => ({ 
  json: { ...ctx, currentFetchPath: f, fetchIndex: idx, totalFiles: files.length } 
}));

const prepareItems = $('Prepare Fetch').all();
const fetchItems = $input.all();
const originalCtx = $('Merge Fly Response').item.json;

const fileContents = {};

for (let i = 0; i < prepareItems.length; i++) {
  const path = prepareItems[i].json.currentFetchPath;
  const fetchResp = fetchItems[i]?.json;

  if (!path) continue;

  let content = fetchResp?.content;

  if (content) {
    try {
      // FULL content - no truncation for AI context
      const decoded = Buffer.from(content, 'base64').toString('utf8');
      fileContents[path] = decoded;
    } catch (e) {
      fileContents[path] = '// Error decoding';
    }
  }
}

return [{ json: { ...originalCtx, fileContents } }];

const query = $fromAI('input', 'Directory path', 'string');
let ctx = {};
try { ctx = $('Merge Files')?.item?.json || {}; } catch (e) {}

const owner = ctx.owner || ctx.site?.owner;
const repo = ctx.repo || ctx.site?.repo;
const branch = ctx.branch || 'main';

if (!owner || !repo) return '{"error":"no repo"}';

let path = '.';
try {
  const parsed = JSON.parse(query);
  path = parsed.path || parsed.input || '.';
} catch { path = query || '.'; }

path = path.replace(/^\/+/, '').replace(/\/+$/, '');
if (path === '' || path === '.') path = '';

try {
  const r = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=1`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json' }
  });

  let files = (r.tree || []).filter(f => f.type === 'blob').map(f => f.path);
  if (path) files = files.filter(f => f.startsWith(path + '/') || f === path);

  return `Files in ${path || 'repository'}:\n${files.slice(0, 50).join('\n')}`;
} catch (e) {
  return `{"error":"${e.message}"}`;
}

const query = $fromAI('input', 'File path', 'string');
let ctx = {};
try { ctx = $('Merge Files')?.item?.json || {}; } catch (e) {}

let filePath = query;
try {
  const parsed = JSON.parse(query);
  filePath = parsed.filePath || parsed.path || parsed.input || query;
} catch { filePath = query; }

filePath = filePath.replace(/^\/+/, '').trim();

// Check if already in context
if (ctx.fileContents && ctx.fileContents[filePath]) {
  return `File already loaded:\n${ctx.fileContents[filePath]}`;
}

const owner = ctx.owner || ctx.site?.owner;
const repo = ctx.repo || ctx.site?.repo;
const branch = ctx.branch || 'main';

if (!owner || !repo) return '{"error":"no repo"}';

try {
  const r = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${branch}`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json' }
  });
