const query = $fromAI('input', 'JSON with oldPath and newPath', 'string');
let ctx = {};
try { ctx = $('Merge Files')?.item?.json || {}; } catch (e) {}

const owner = ctx.owner || ctx.site?.owner;
const repo = ctx.repo || ctx.site?.repo;
const branch = ctx.branch || 'main';

if (!owner || !repo) return '{"error":"no repo"}';

let oldPath, newPath;
try {
  const parsed = JSON.parse(query);
  oldPath = parsed.oldPath || parsed.original_file_path;
  newPath = parsed.newPath || parsed.new_file_path;
} catch {
  return '{"error":"Invalid JSON. Use: {\"oldPath\": \"...\", \"newPath\": \"...\"}"}';
}

if (!oldPath || !newPath) return '{"error":"Both oldPath and newPath required"}';

try {
  // Read old file
  const existing = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${oldPath}?ref=${branch}`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json' }
  });

  // Create new file
  await this.helpers.httpRequest({
    method: 'PUT',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${newPath}`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json', 'Content-Type': 'application/json' },
    body: JSON.stringify({ message: `Rename ${oldPath} to ${newPath}`, content: existing.content, branch })
  });

  // Delete old file
  await this.helpers.httpRequest({
    method: 'DELETE',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${oldPath}`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json', 'Content-Type': 'application/json' },
    body: JSON.stringify({ message: `Rename ${oldPath} to ${newPath} (delete old)`, sha: existing.sha, branch })
  });

  return JSON.stringify({ success: true, renamed: { from: oldPath, to: newPath } });
} catch (e) {
  return `{"error":"${e.message}"}`;
}

