}

try {
  const searchQuery = path ? `${pattern} path:${path}` : pattern;
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/search/code?q=${encodeURIComponent(searchQuery)}+repo:${owner}/${repo}`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json' }
  });

  if (response.items?.length > 0) {
    const results = response.items.slice(0, 15).map(item => `- ${item.path}`).join('\n');
    return `Found "${pattern}" in ${response.total_count} files:\n${results}`;
  }
  return `No results for "${pattern}"`;
} catch (e) {
  return `{"error":"${e.message}"}`;
}

