const query = $fromAI('input', 'URL to fetch', 'string');

let url = query;
try {
  const parsed = JSON.parse(query);
  url = parsed.url || parsed.input || query;
} catch { url = query; }

if (!url.startsWith('http')) url = 'https://' + url;

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    headers: { 'User-Agent': 'Mozilla/5.0 (compatible; AutoMate/1.0)', 'Accept': 'text/html,application/json,text/plain' }
  });

  let content = typeof response === 'string' ? response : JSON.stringify(response, null, 2);

  // Basic HTML to text
  content = content
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  return `Content from ${url}:\n${content.substring(0, 8000)}`;
} catch (e) {
  return `{"error":"Failed to fetch: ${e.message}"}`;
}

const query = $fromAI('input', 'Search query', 'string');

let searchQuery = query;
try {
  const parsed = JSON.parse(query);
  searchQuery = parsed.query || parsed.input || query;
} catch { searchQuery = query; }

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.duckduckgo.com/?q=${encodeURIComponent(searchQuery)}&format=json&no_html=1`,
    headers: { 'User-Agent': 'AutoMate/1.0' }
  });

  let results = [];
  if (response.AbstractText) results.push(`**Summary:** ${response.AbstractText}`);
  if (response.AbstractURL) results.push(`**Source:** ${response.AbstractURL}`);
  if (response.RelatedTopics?.length > 0) {
    results.push('\n**Related:**');
    response.RelatedTopics.slice(0, 5).forEach(topic => {
      if (topic.Text) results.push(`- ${topic.Text}`);
    });
  }

  return results.length > 0 ? `Search results for "${searchQuery}":\n${results.join('\n')}` : `No instant answers for "${searchQuery}"`;
} catch (e) {
  return `{"error":"${e.message}"}`;
}

