const ctx = $('Merge Files').item.json;
const raw = $('AI Plan').item.json;
let out = raw?.output || raw?.text || '';
if (typeof out === 'object') out = JSON.stringify(out);

const filesCreated = [];
const thinking = [];
const steps = raw?.intermediateSteps || [];

for (const step of steps) {
  const action = step?.action;
  const obs = step?.observation || '';

  // Extract thinking
  if (action?.log) {
    const textMatch = action.log.match(/\[\{"index":0,"type":"text","text":"([^"]+)"/);
    if (textMatch) thinking.push(textMatch[1]);
  }

  // Track file changes
  if (action?.tool === 'create_file') {
    try {
      const o = typeof obs === 'string' ? JSON.parse(obs) : obs;
      if (o.success && o.file) filesCreated.push({ file: o.file, action: o.action || 'updated' });
    } catch (e) {
      try {
        const inp = typeof action.toolInput === 'string' ? JSON.parse(action.toolInput) : action.toolInput;
        if (inp.filePath) filesCreated.push({ file: inp.filePath, action: 'created' });
      } catch (e2) {}
    }
  }

  if (action?.tool === 'delete_file') {
    try {
      const o = typeof obs === 'string' ? JSON.parse(obs) : obs;
      if (o.success) filesCreated.push({ file: o.deleted, action: 'deleted' });
    } catch (e) {}
  }

  if (action?.tool === 'rename_file') {
    try {
      const o = typeof obs === 'string' ? JSON.parse(obs) : obs;
      if (o.success) filesCreated.push({ file: o.renamed?.to, action: 'renamed' });
    } catch (e) {}
  }
}

const plan = {
  humanSummary: out || (filesCreated.length ? 'Updated: ' + filesCreated.map(f => f.file).join(', ') : 'Processed'),
  fileTargets: filesCreated,
  thinking,
  warnings: filesCreated.length === 0 && steps.length > 0 ? ['No files modified'] : []
};

return [{ json: { ...ctx, plan, filesCreated: filesCreated.map(f => f.file), iterations: steps.length } }];

